  uf.add(5);
  if (uf.numGroups() !== 3) {
    throw new Error(`\ngot: ${uf.numGroups()}, want: 3\n`);
  }
  uf.union(4, 5);
  if (uf.numGroups() !== 2) {
    throw new Error(`\ngot: ${uf.numGroups()}, want: 2\n`);
  }

  // Test find after unions
  const uf2 = new CustomUnionFind();
  uf2.add(1);
  uf2.add(2);
  uf2.add(3);
  uf2.union(1, 2);
