  uf3.add(1);
  uf3.add(2);
  uf3.union(1, 2);
  uf3.union(1, 2);
  if (uf3.numGroups() !== 1) {
    throw new Error(`\ngot: ${uf3.numGroups()}, want: 1\n`);
  }
}

